package application_test
import ("context"; "errors"; "os"; "path/filepath"; "testing"; "evidence/internal/application"; "evidence/internal/domain"; "evidence/internal/repository")
func TestBug10SuspendedRejectsLateReview(t *testing.T){ctx:=context.Background(); root:=t.TempDir(); repo,_:=repository.NewFileRepository(root); _=repo.SaveConditionVersion(ctx,domain.ConditionVersion{ID:"cv",RequestID:"r"}); _=repo.SaveRequest(ctx,domain.AuthorizationRequest{ID:"r",Status:domain.StatusSuspended,CurrentVersionID:"cv",Version:5}); err:=application.NewAuthorizationService(repo).Review(ctx,"r","late",true,"late"); if !errors.Is(err,domain.ErrInvalidStateTransition){t.Fatalf("late review: %v",err)}; got,_:=repo.GetRequest(ctx,"r"); if got.Status!=domain.StatusSuspended||got.Version!=5{t.Fatalf("request: %#v",got)}; if files,e:=os.ReadDir(filepath.Join(root,"review_rounds")); e==nil&&len(files)!=0{t.Fatalf("rounds=%d",len(files))}}
